%[text] ## Test Wrapper for generate\_rwa\_disturbance 
% Define time parameters and generate the time vector
fs = 1000; % Sampling frequency in Hz
t_span = [0, 60]; % Start and end time in seconds
t = t_span(1) : 1/fs : t_span(2);

% Define external forcing profiles using helper function
rpm_start = 100; rpm_end = 200; % RPM
unbalance = 0.1; % kgm
rotor_inertia = 0.5 * 10 * 0.2^2; % (Shape Factor) x (Mass) x (Radius)^2
[Fx, Fy, M_theta] = fem.generate_rwa_disturbance(t, rpm_start, rpm_end, unbalance, rotor_inertia);
% Plot X Disturbance
figure; hold on; %[output:17f76dc8]
plot(t, Fx); %[output:17f76dc8]
xlabel('Time (s)'); %[output:17f76dc8]
ylabel('Disturbance'); %[output:17f76dc8]
legend('F_x', 'Location', 'best'); %[output:17f76dc8]
grid on; %[output:17f76dc8]
title('Reaction Wheel Assembly X Disturbance Profiles'); %[output:17f76dc8]
xlim(t_span); hold off %[output:17f76dc8]
% Plot Y disturbance
figure; hold on; %[output:18012a88]
plot(t, Fy); %[output:18012a88]
xlabel('Time (s)'); %[output:18012a88]
ylabel('Disturbance'); %[output:18012a88]
legend( 'F_y', 'Location', 'best'); %[output:18012a88]
grid on; %[output:18012a88]
title('Reaction Wheel Assembly Y Disturbance Profiles'); %[output:18012a88]
xlim(t_span); hold off %[output:18012a88]
% Plot theta disturbance
figure; hold on; %[output:0bd565fd]
plot(t, M_theta); %[output:0bd565fd]
xlabel('Time (s)'); %[output:0bd565fd]
ylabel('Disturbance'); %[output:0bd565fd]
legend('M_\theta', 'Location', 'best'); %[output:0bd565fd]
grid on; %[output:0bd565fd]
title('Reaction Wheel Assembly Torque Disturbance Profiles'); %[output:0bd565fd]
xlim(t_span); hold off %[output:0bd565fd]

